import{_ as t,o as n,c as r,ah as i}from"./chunks/framework.DDXs_i7t.js";const c=JSON.parse('{"title":"14. März: Das Wienerlied vom Gustl beim AKIfair","description":"Der (fiktive) Soundtrack zu Teil 4: August Wöginger landet in der Innstraße 7 beim Bewerbungstraining.","frontmatter":{"title":"14. März: Das Wienerlied vom Gustl beim AKIfair","description":"Der (fiktive) Soundtrack zu Teil 4: August Wöginger landet in der Innstraße 7 beim Bewerbungstraining.","date":"2026-03-14T00:00:00.000Z"},"headers":[],"relativePath":"logbuch/2026-03-14-wienerlied-akifair.md","filePath":"logbuch/2026-03-14-wienerlied-akifair.md"}'),a={name:"logbuch/2026-03-14-wienerlied-akifair.md"};function s(d,e,o,l,u,h){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="🎼-d-harte-prosa-in-da-innstraßn-wienerlied" tabindex="-1">🎼 D&#39;Harte Prosa in da Innstraßn (Wienerlied) <a class="header-anchor" href="#🎼-d-harte-prosa-in-da-innstraßn-wienerlied" aria-label="Permalink to &quot;🎼 D&#39;Harte Prosa in da Innstraßn (Wienerlied)&quot;">​</a></h1><p>Heute, am Samstag den 14. März 2026, veröffentlichen wir exklusiv den vollständigen Text zu unserem „Leaked Soundtrack“. In diesem klassischen Wienerlied thematisieren wir den fiktiven tiefen Fall eines Polit-Stars, der sich plötzlich in der Realität der Tiroler Arbeitsmarkt-Bürokratie wiederfindet.</p><h3 id="der-text-zum-mitsingen" tabindex="-1"><strong>Der Text zum Mitsingen</strong> <a class="header-anchor" href="#der-text-zum-mitsingen" aria-label="Permalink to &quot;**Der Text zum Mitsingen**&quot;">​</a></h3><p><strong>(1. Strophe)</strong> In da Löwelstraßn, do war’s amoi schee, jetzt muaß da Gustl in d&#39;Innstraßn geh. Des Dienstauto weg und de Macht is dahi, jetzt schreibt eam des AMS: „Kumm her zu mi!“ Er war amoi wer, a ganz hoarter Hund, jetzt is er nur mehr a Punkt im Befund. De Krawattn is locka, de Stirn voller Falten, wer soll denn den Gustl am Markt noch erhalten?</p><p><strong>(Refrain)</strong> Owa Gustl, jetzt muaßt zum AKIfair, dort wird dei Leben erst richtig schwer. In da Innstraßn sieben, do sitzt er jetzt drin, und sucht in de Kurse an tieferen Sinn. Mit’m Kulli in da Hand und am leeren Blick, träumt er von der Macht und dem alten Glück. Ja, beim AKIfair, do lernt er geschwind: Dass a jeder am Ende nur a Bittsteller find’t.</p><p><strong>(2. Strophe)</strong> De Trainerin schaut eam recht mitleidig an: „Na Gustl, erzähl, wos host denn getan?“ Er richt’ se kurz auf, de Brust wird eam breit: „I hob Prosa g’schrieben für d&#39;Ewigkeit! I hob Videos g’mocht, so hoart wie a Stan, i hob gsagt, wer brav is, der is net allein!“ Doch de Dame, de gähnt: „Des is ois recht nett, owa schreib ma des liaba ins Motivations-Skelett.“</p><p><strong>(3. Strophe)</strong> „Host an Computer? Kannst E-Mail verschicken? Oder kannst nur de Leit in de Pfanne haun, kicken?“ Er schaut auf de Wand, do hängt a Plakat: „Integration is des, wos ma hier hat.“ Er denkt an den Thomas, den Schmid und de Chats, jetzt sitzt er beim Coaching, des is ka Hetz. „Bewerbungstraining“, des is jetzt sein Los, statt Staatssekretär nur a Arbeitslos-Floß.</p><p><strong>(Refrain)</strong> Owa Gustl, jetzt muaßt zum AKIfair, dort wird dei Leben erst richtig schwer. In da Innstraßn sieben, do sitzt er jetzt drin, und sucht in de Kurse an tieferen Sinn. Mit’m Kulli in da Hand und am leeren Blick, träumt er von der Macht und dem alten Glück. Ja, beim AKIfair, do lernt er geschwind: Dass a jeder am Ende nur a Bittsteller find’t.</p><p><strong>(Outro)</strong> Am Abend do schleicht er zum Goldenen Dachl, und trinkt an Roten, des oarme Patschl. De Viralität is eam heute egal, beim AKIfair war’s de reinste Qual. Harte Prosa, weiche Knie, so endet de Macht in da Bürokratie.</p><hr><p>👉 <a href="/medien.html">Zurück zum Forensik-Dashboard</a> 👉 <a href="/statistik.html">Zum aktuellen Viralitäts-Index</a></p><hr><p><em>V veröffentlicht am 14. März 2026. Eine künstlerische Auseinandersetzung mit der Realität.</em></p>',13)])])}const g=t(a,[["render",s]]);export{c as __pageData,g as default};
